namespace vs=reader::viewstore;namespace pv=reader::pdfview;using Path=std::filesystem::path;
static unsigned checks=0;
static void check(bool value,const char* label){if(!value)throw std::runtime_error(label);++checks;}
template<class F>static void rejects(F f,const char* label){bool rejected=false;try{f();}catch(const std::exception&){rejected=true;}check(rejected,label);}
static QByteArray json(const QJsonObject& o){return QJsonDocument(o).toJson(QJsonDocument::Compact);}
static QString hash(const QByteArray& b){return QString::fromLatin1(underlay::digest(b).toHex());}
struct Fixture{Path root;library::Document document;QByteArray descriptor,source;explicit Fixture(const Path& folder){underlay::privateDirectory(folder);source="%PDF-1.7 view-store authored identity fixture";underlay::atomicFile(folder/"input.pdf",source);{library::Store library(folder/"library");document=library.importDocument(folder/"input.pdf","View receipt",[](const Path&,const QString&){return library::Inspection{3,"pdf-source-v1",{}};});}root=library::documentRoot(folder/"library",document.id);descriptor=underlay::readBounded(root/"document.json",8192);}void unchanged(){check(underlay::readBounded(root/"document.json",8192)==descriptor,"immutable descriptor unchanged");check(underlay::readBounded(root/"source.pdf",1024)==source,"source bytes unchanged");}};
static pv::View zoom(double value){pv::View v;v.zoom=value;return v;}
static void file(const Path& p,const QByteArray& data){underlay::privateDirectory(p.parent_path());underlay::atomicFile(p,data);}
static QByteArray emptyHighlights(const QString& document,bool records=false){QJsonObject payload{{"version",1},{"document",document},{"pageId",QString(64,'b')},{"style","double-underline-rgb32-v1"},{"records",records?QJsonArray{QJsonObject{}}:QJsonArray{}}};return json({{"payload",payload},{"sha256",hash(json(payload))}});}
